/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: BylineCredit, BylineSegment
 *   Functions: toBylineCredit, catalogBylineSegments, capCatalogByline, composeCatalogByline,
 *              catalogDisplayByline, composePlainNameByline
 *   Constants: undocumentedAttributionByline, maximumBylineLength, bylineTruncationMarker,
 *              defaultBylineSeparator
 * Internal
 *   Types: GraphemeSegmenter
 *   Functions: longestPrefix, cutName
 *   Constants: performingRoles
 * @end-catalog */

/**
 * The only server byline composer. Listener v1, legacy public catalog and Library projections
 * all build `displayByline` (or a Library creator) here, so every surface shows the same text.
 * Pure: callers resolve subject names (already trimmed) and pass them in; no I/O happens here.
 */
import type {
    AttributionStatus,
    CatalogCredit,
    CatalogCreditRole,
    CatalogCreditSubjectType
} from '../../models/catalogCredit';

/** Byline shown for explicit unknown attribution. */
export const undocumentedAttributionByline = 'Attribution not documented';

/**
 * Longest byline in UTF-16 units. A UTF-16 bound also bounds Android code points and iOS
 * grapheme clusters, the units each native client counts against its own 500 limit.
 */
export const maximumBylineLength = 500;

/** Appended after the last whole name that fits when a byline is shortened. */
export const bylineTruncationMarker = '\u2026';

/** Separator after a name whose Credit has no usable join phrase. */
export const defaultBylineSeparator = ', ';

/** One stored Credit as the byline sees it; name is '' when the subject is hidden, unavailable or unnamed. */
export interface BylineCredit {
    subjectType: CatalogCreditSubjectType;
    role: CatalogCreditRole;
    order: number;
    name: string;
    joinPhrase?: string;
}

/** One shown byline name and the text placed before it; the first separator is ''. */
export interface BylineSegment {
    separator: string;
    name: string;
}

const performingRoles = new Set<CatalogCreditRole>(['primary', 'featured', 'performer']);

/** Pairs a validated stored Credit with its resolved display name. */
export const toBylineCredit = (credit: CatalogCredit, name: string): BylineCredit => ({
    subjectType: credit.subjectType,
    role: credit.role,
    order: credit.order,
    name,
    ...(credit.joinPhrase === undefined ? {} : { joinPhrase: credit.joinPhrase })
});

/**
 * Ordered shown names with their separators. Credits are ordered by `order` (ties keep input
 * order), hidden ones included so they still break adjacency. The shown tier is the visible
 * primary, featured and performer Credits; without them the visible Organization Credits;
 * otherwise every visible Credit. A repeated name appears once, at its first position. A name's
 * join phrase is used only when the next shown name belongs to the very next Credit, so an
 * omitted Credit never leaves a stray or misleading phrase; otherwise `, ` is used. Exported
 * for property tests.
 */
export const catalogBylineSegments = (credits: readonly BylineCredit[]): ReadonlyArray<BylineSegment> => {
    const sorted = credits
        .map((credit, index) => ({ credit, index }))
        .sort((left, right) => left.credit.order - right.credit.order || left.index - right.index)
        .map(({ credit }) => credit);
    const visible = sorted.filter((credit) => credit.name !== '');
    const performing = visible.filter((credit) => performingRoles.has(credit.role));
    const institutional = visible.filter((credit) => credit.subjectType === 'organization');
    const tier = new Set(performing.length > 0 ? performing : institutional.length > 0 ? institutional : visible);

    const seenNames = new Set<string>();
    const shown: Array<{ name: string; position: number; joinPhrase?: string }> = [];
    sorted.forEach((credit, position) => {
        if (!tier.has(credit) || seenNames.has(credit.name)) return;
        seenNames.add(credit.name);
        shown.push({ name: credit.name, position, joinPhrase: credit.joinPhrase });
    });
    return shown.map((entry, index) => {
        const previous = shown[index - 1];
        const separator = !previous
            ? ''
            : previous.joinPhrase !== undefined && entry.position === previous.position + 1
                ? previous.joinPhrase
                : defaultBylineSeparator;
        return { separator, name: entry.name };
    });
};

/** Minimal typing for Intl.Segmenter, which the server's ES2020 library types do not declare. */
type GraphemeSegmenter = new (
    locales?: string,
    options?: { granularity: 'grapheme' }
) => { segment(value: string): Iterable<{ segment: string }> };

/** Appends whole units (graphemes or code points) while the result stays within the limit. */
const longestPrefix = (units: Iterable<string>, limit: number) => {
    let prefix = '';
    for (const unit of units) {
        if (prefix.length + unit.length > limit) break;
        prefix += unit;
    }
    return prefix;
};

/**
 * Cuts one oversized name at the last grapheme boundary within the limit. Without
 * Intl.Segmenter, or when the first grapheme alone is too long, it cuts at the last code point
 * boundary instead, which still never splits a surrogate pair. Trailing whitespace is trimmed
 * so the marker never follows a space.
 */
const cutName = (name: string, limit: number) => {
    const Segmenter = (Intl as unknown as { Segmenter?: GraphemeSegmenter }).Segmenter;
    // Grapheme rules look only one code point to the right, so boundaries up to the limit are
    // the same in this bounded window (two extra units keep that code point whole).
    const bounded = name.slice(0, limit + 2);
    const graphemes = Segmenter
        ? Array.from(new Segmenter(undefined, { granularity: 'grapheme' }).segment(bounded), ({ segment }) => segment)
        : [];
    const cut = longestPrefix(graphemes, limit) || longestPrefix(name, limit);
    return cut.replace(/\p{White_Space}+$/u, '');
};

/**
 * Joins segments within 500 UTF-16 units. A longer byline ends after the last whole name that
 * fits, followed by `…`; when even the first name does not fit, that name is cut instead.
 */
export const capCatalogByline = (segments: ReadonlyArray<BylineSegment>): string => {
    const full = segments.map((segment) => segment.separator + segment.name).join('');
    if (full.length <= maximumBylineLength) return full;
    let prefix = '';
    for (const segment of segments) {
        const next = prefix + segment.separator + segment.name;
        if (next.length + bylineTruncationMarker.length > maximumBylineLength) break;
        prefix = next;
    }
    if (prefix) return prefix + bylineTruncationMarker;
    return cutName(segments[0].name, maximumBylineLength - bylineTruncationMarker.length)
        + bylineTruncationMarker;
};

/** Composes the byline for documented attribution; '' when no Credit subject is visible. */
export const composeCatalogByline = (credits: readonly BylineCredit[]) =>
    capCatalogByline(catalogBylineSegments(credits));

/** Composes the byline shown for one owner's attribution state. */
export const catalogDisplayByline = (status: AttributionStatus, credits: readonly BylineCredit[]): string =>
    status === 'unknown' ? undocumentedAttributionByline : composeCatalogByline(credits);

/**
 * Legacy fallback for unmigrated owners and the Credit-reads rollback. It keeps the pre-Credit
 * presentation (empty names dropped, every other name kept, even a repeated one, joined with
 * `, `) and adds only the shared length cap.
 */
export const composePlainNameByline = (names: readonly string[]): string => {
    const segments: BylineSegment[] = [];
    for (const name of names) {
        if (!name) continue;
        segments.push({ separator: segments.length > 0 ? defaultBylineSeparator : '', name });
    }
    return capCatalogByline(segments);
};
